  "definitions": [
    {
      "term": {
        "text": "reference type",
        "refs": ["Q0001"]
      },
      "definition_text": {
        "text": "a type whose variable holds the address of an object in memory rather than the actual object itself",
        "refs": ["Q0001"]
      },
      "context": null
    }
  ],
  "examples": [],
  "explanations": [
    {
      "topic": {
        "text": "reference vs primitive assignment",
        "refs": ["Q0002"]
      },
      "explanation_text": {
        "text": "When a reference type variable is assigned to another, the second variable receives the same memory address, so both variables refer to the same object; changing the object through one variable is visible through the other.",
        "refs": ["Q0002", "Q0003", "Q0004"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "Primitive variables store the actual value in their memory location.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Reference type variables store a reference (address) to an object in memory.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Assigning one reference variable to another copies the reference, not the object.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Two reference variables that reference the same object will reflect changes made through either variable.",
        "refs": ["Q0003", "Q0004"]
      },
      "fact_type": null
    }
  ],
